void read_inputs() {
    // Wait until the game sets new input
    while (!new_input_ready) {
        usleep(1000); // sleep 1ms to avoid busy wait
    }

    // Apply the player input to robber position
    robber_x += player_dx;
    robber_y += player_dy;

    printf("Cop: (%d, %d), Robber: (%d, %d)\n", cop_x, cop_y, robber_x, robber_y);

    // Reset flag
    player_dx = 0;
    player_dy = 0;
    new_input_ready = 0;
}

